"""Bind actual failure faces and telemetry; propose, but do not enable, stair motion."""
import pathlib,json,math,hashlib
H=pathlib.Path(__file__).resolve().parent;ROOT=next(p for p in H.parents if (p/'voxel_character').is_dir());CITY=ROOT/'world_city/concept_city_v3'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def canonical(v):return hashlib.sha256(json.dumps(v,separators=(',',':'),allow_nan=False).encode()).hexdigest()
def read(p):return json.loads(p.read_bytes())
def write(p,d):
 p.parent.mkdir(exist_ok=True)
 with p.open('x')as f:json.dump(d,f,indent=2,allow_nan=False);f.write('\n')
def main():
 prepared=read(H/'prepared.json');s=pathlib.Path(prepared['sources']['actual_r8_candidate']['path']);scene=read(s);assert sha(s)==prepared['sources']['actual_r8_candidate']['sha256'];oldpath=CITY/'evidence/visual_registered_common_r7/scene.json';old=read(oldpath)
 lookup={canonical(old['surfaces']['bank'][i:i+3]):i//3 for i in range(0,len(old['surfaces']['bank']),3)};p=prepared['coverage']['stair_local_to_world'];c=math.cos(p['yaw_rad']);sn=math.sin(p['yaw_rad'])
 def local(v):
  x,y,z=[v[i]-p['position_m'][i]for i in range(3)];return [c*x-sn*z,y,sn*x+c*z]
 rows=[]
 for i in [10037,10038,10047,10048]:
  tri=scene['surfaces']['bank'][3*i:3*i+3];rows.append({'material':'bank','triangle_index':i,'source_triangle_sha256':canonical(tri),'triangle_xyz_m':tri,'triangle_stair_local_xyz_m':[local(v)for v in tri],'identical_prior_r7_bank_triangle_index':lookup.get(canonical(tri))})
 base=read(H/'evidence/capsule_baseline_initial.json');trace=read(H/'evidence/support_trace.json');r=trace['routes'][0];baseline=next(q for q in base['routes']if q['id']==r['id']);parity={k:r[k]==baseline[k]for k in ['status','end_position','physics_frames','ground_ray_miss_frames','not_on_floor_frames','obstacle_contact_ids','distance_walked_m']};assert all(parity.values())
 contacts=[]
 for route in base['routes']:
  for contact in route['obstacle_contact_samples']:
   if contact['collider_id']=='SCENE:R8:estate':contacts.append(dict(contact,route_id=route['id'],contact_stair_local_xyz_m=local(contact['position'])))
 report={'schema':'riverstone.r8.stair_failure_diagnosis.v1','scene':prepared['sources']['actual_r8_candidate'],'original_failure_seal_sha256':sha(H/'freeze_initial_failure.json'),'prior_r7_scene':{'path':str(oldpath.relative_to(ROOT)),'sha256':sha(oldpath)},'actual_contact_bank_triangles':rows,'scene_contact_samples':contacts,'first_riser':{'native_placement_id':p['id'],'local_z_m':1.2,'lower_y_world_m':8.1,'upper_y_world_m':8.25,'rise_m':.15,'going_m':.3,'clear_width_m':2.4},'descent_support':{'source_trace_sha256':sha(H/'evidence/support_trace.json'),'observer_only_motion_parity':parity,'ungrounded_frames':len(r['support_trace']),'long_ray_misses':sum(not q['long_ray_hit']for q in r['support_trace']),'max_feet_gap_m':max(q.get('feet_gap_m',0)for q in r['support_trace']),'max_gap_record':max(r['support_trace'],key=lambda q:q.get('feet_gap_m',0))},'interpretation':['Lower landing is obstructed by retained scene bank faces at stair-local z=.2, before the first intended native riser.','Another retained bank wall cuts through the native first flight near local z=4.066.','Both native ascent edge routes independently block at the intended .15 m first riser.','Descent support loss is actual flight above intact native treads.','No controller adjustment should conceal the retained bank obstruction.']}
 write(H/'diagnostics/failure_geometry.json',report)
 proposal={'status':'PROPOSAL_ONLY_NOT_IMPLEMENTED','required_geometry_precondition':'Explicit finite clipping of offending retained bank faces against accepted stair/collar ownership, preserving exterior banks; parent-owned revised scene and hash required.','controller_source':prepared['sources']['original_controller'],'candidate_location':'A new child candidate under this r06 revision, with original controller retained byte-identical.','parameters':{'capsule_radius_m':.3,'capsule_height_m':1.8,'speed_mps':4,'physics_hz':60,'maximum_step_up_m':.18,'maximum_step_down_m':.18,'actual_authored_stair_riser_m':.15},'algorithm_requirements':['Only actual grounded blocked horizontal motion may request upward stepping.','Full capsule collision sweeps upward, for the same intended horizontal frame displacement, then down onto an actual floor must all succeed.','Require floor normal and headroom clearance at the landing; apply accepted movement through collision-resolved motion, never route position assignment.','Bounded step-down sweep may keep a previously grounded capsule supported on an actual next tread; never snap across a true void or extend the finite floor.','Preserve original no-step mode and every failing report.','Keep native stair collision and visual geometry, with no continuous ramp proxy over intentional stairs.'],'required_tests':['Revised scene original-controller replay before candidate comparison.','Same sixteen baseline and pause/edge/guard cases.','Additional .25 m riser, low-headroom, side-guard and finite-water controls must fail appropriately.','Actual tread stops and restart both directions; strict short-ray support, bounded rise/drop, collision sweeps and no route snapping.'],'acceptance':'No candidate or production capability pass until actual physics tests on hash-bound geometry.'}
 write(H/'step_capability_proposal.json',proposal)
 write(H/'diagnostics/freeze_diagnosis.json',{'status':'SEALED_BOUNDED_DIAGNOSIS_AND_UNEXECUTED_PROPOSAL','files':{str(p.relative_to(ROOT)):sha(p)for p in [H/'SupportTrace.gd',H/'SupportTrace.tscn',H/'evidence/support_trace.json',H/'evidence/support_trace.log',H/'diagnostics/failure_geometry.json',H/'step_capability_proposal.json',H/'diagnose_and_propose.py']}})
 print(json.dumps({'report_sha256':sha(H/'diagnostics/failure_geometry.json'),'diagnosis_seal_sha256':sha(H/'diagnostics/freeze_diagnosis.json'),'prior_r7_bank_indices':[r['identical_prior_r7_bank_triangle_index']for r in rows],'motion_parity':parity}))
if __name__=='__main__':main()
